#include "propagation_policy.hpp"
#include "resident/storage/common_codec.hpp"
namespace hanmo::resident {
const char* propagation_category_name(KnowledgeCategory v)noexcept {switch(v){case KnowledgeCategory::supply:return "supply";case KnowledgeCategory::arrear:return "arrear";case KnowledgeCategory::action_outcome:return "action_outcome";case KnowledgeCategory::offer_discovery:return "offer_discovery";case KnowledgeCategory::contact_location:return "contact_location";case KnowledgeCategory::legacy_social:return "legacy_social";case KnowledgeCategory::intelligence_probe:return "intelligence_probe";case KnowledgeCategory::cultural_content:return "cultural_content";}return nullptr;}
Outcome<KnowledgeCategory> read_propagation_category(const StableId& name){for(Integer n=0;n!=8;++n){auto v=static_cast<KnowledgeCategory>(n);if(name==propagation_category_name(v))return {true,v,{}};}return {false,{},common_failure("UnknownPropagationCategory",name).error};}
Status validate_propagation_policy(const PropagationPolicy& p,const PropagationPolicyLimits& limits){
 if(limits.max_expiry_ticks<=0||limits.max_cooldown_ticks<=0)return common_failure("PropagationContentLimitsRequired");
 if(p.policy_id.empty()||p.rule_version.empty()||p.max_candidates<1||p.max_candidates>64||p.max_dispatches_per_review<1||p.max_dispatches_per_review>16||p.max_dispatches_per_review>p.max_candidates||p.expiry_ticks<1||p.expiry_ticks>limits.max_expiry_ticks||p.cooldown_ticks<1||p.cooldown_ticks>limits.max_cooldown_ticks)return common_failure("InvalidPropagationPolicy",p.policy_id);
 const auto& t=p.relation_thresholds_by_social_kind;if(t.cooperative<0||t.cooperative>300||t.selfish<0||t.selfish>300)return common_failure("InvalidPropagationThreshold",p.policy_id);
 if(p.enabled_categories.empty()||p.enabled_categories.size()>8||p.allowed_channels.empty()||p.allowed_channels.size()>4)return common_failure("InvalidPropagationSelection",p.policy_id);
 for(std::size_t i=0;i<p.enabled_categories.size();++i){if(!propagation_category_name(p.enabled_categories[i]))return common_failure("UnknownPropagationCategory",p.policy_id);for(std::size_t j=0;j<i;++j)if(p.enabled_categories[i]==p.enabled_categories[j])return common_failure("DuplicatePropagationCategory",p.policy_id);}
 for(std::size_t i=0;i<p.allowed_channels.size();++i){if(!message_channel_name(p.allowed_channels[i]))return common_failure("UnknownPropagationChannel",p.policy_id);for(std::size_t j=0;j<i;++j)if(p.allowed_channels[i]==p.allowed_channels[j])return common_failure("DuplicatePropagationChannel",p.policy_id);}
 return common_success();
}
Outcome<PropagationPolicy> decode_propagation_policy(const BoundaryValue& value,const PropagationPolicyLimits& limits){try{using namespace boundary;const StableId path="PropagationPolicy/1";fields(value,{"policy_id","rule_version","enabled_categories","allowed_channels","max_candidates","max_dispatches_per_review","relation_thresholds_by_social_kind","expiry_ticks","cooldown_ticks"},{},path);PropagationPolicy p;p.policy_id=get_string(value,"policy_id",path);p.rule_version=get_string(value,"rule_version",path);p.max_candidates=get_int(value,"max_candidates",path);p.max_dispatches_per_review=get_int(value,"max_dispatches_per_review",path);p.expiry_ticks=get_int(value,"expiry_ticks",path);p.cooldown_ticks=get_int(value,"cooldown_ticks",path);const auto& t=field(value,"relation_thresholds_by_social_kind",path);fields(t,{"cooperative","selfish"},{},path);p.relation_thresholds_by_social_kind={get_int(t,"cooperative",path),get_int(t,"selfish",path)};
 for(const auto& n:array(field(value,"enabled_categories",path),path)){auto r=read_propagation_category(string(n,path));if(!r.ok)return {false,{},r.error};p.enabled_categories.push_back(r.value);}for(const auto& n:array(field(value,"allowed_channels",path),path)){auto r=read_message_channel_kind(string(n,path));if(!r.ok)return {false,{},r.error};p.allowed_channels.push_back(r.value);}auto valid=validate_propagation_policy(p,limits);if(!valid.ok)return {false,{},valid.error};return {true,std::move(p),{}};
 }catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status emit_propagation_policy_fields(ProjectionWriter& w,const PropagationPolicy& p){w.field("policy_id",p.policy_id);w.field("rule_version",p.rule_version);w.sequence("enabled_categories",p.enabled_categories,[](auto& x,const auto& v){const auto* name=propagation_category_name(v);return name?x.field("",StableId{name}):x.reject("UnknownPropagationCategory");});w.sequence("allowed_channels",p.allowed_channels,[](auto& x,const auto& v){const auto* name=message_channel_name(v);return name?x.field("",StableId{name}):x.reject("UnknownPropagationChannel");});w.field("max_candidates",p.max_candidates);w.field("max_dispatches_per_review",p.max_dispatches_per_review);w.object("relation_thresholds_by_social_kind",[&](auto& x){x.field("cooperative",p.relation_thresholds_by_social_kind.cooperative);return x.field("selfish",p.relation_thresholds_by_social_kind.selfish);});w.field("expiry_ticks",p.expiry_ticks);return w.field("cooldown_ticks",p.cooldown_ticks);}
}
